      {
        "title": "Вантажі на клині та умови початку руху",
        "text": "Останній приклад — задача два п’ятнадцять. Один вантаж лежить на похилій площині, другий висить на нитці через ідеальний блок. Спочатку вони нерухомі. Потрібно визначити, за яких відношень мас підвішений вантаж почне опускатися або підніматися. На похилий вантаж діють тяжіння, нормальна реакція, натяг і тертя. На підвішений — тяжіння і натяг. Проєкція сили тяжіння вздовж площини дорівнює масі, помноженій на джі та синус кута нахилу; перпендикулярна складова містить косинус. На межі руху тертя спокою досягає максимуму, що дорівнює коефіцієнту тертя, помноженому на нормальну реакцію. Якщо підвішений вантаж намагається опуститися, похилий вантаж намагається піднятися, тому тертя спрямоване вниз по площині. Відношення мас другого до першого на межі дорівнює синусу кута плюс коефіцієнт тертя, помножений на косинус кута. Якщо підвішений вантаж намагається піднятися, тертя змінює напрям; нижня межа — синус кута мінус коефіцієнт тертя, помножений на косинус. За додатних мас ідеальна система починає рухатися вниз для другого вантажу вище верхньої межі, а вгору — нижче нижньої межі, якщо ця межа додатна. Між межами можливий спокій. Запис заняття обривається, тому завершення цього прикладу є додатковим навчальним розв’язанням. Для захисту поясни, чому тертя змінює напрям, чому нормальна реакція містить косинус і чому на межі руху використовують рівновагу."
      }
