    "source": "Записи 21.09.26ch1.mp4 та 21.09.26ch2.mp4. Таймкоди від початку відповідної частини. Усні пояснення переказано; сучасні уточнення, тренувальні задачі та повна формула третього закону позначені як додаткова теорія. Запис перервано до завершення теми. Акценти лектора — переказ за попереднім конспектом, не дослівні цитати. Нові задачі: адаптовані умови зі збірника С. О. Подласова (2023), розв’язання та схеми підготовлено окремо.",
