'use strict';
// Shared renderer for notes and practice. Original source data is not executed as HTML.
const guideEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function guideMath(m){const src=window.GUIDE_ASSETS?.[m]||window.MATH_ASSETS?.[m];return src?`<div class="guide-math"><img class="typeset" src="${guideEscape(src)}" alt="Математична формула" loading="eager"></div>`:'';}
function guideSymbols(rows,open=true){if(!rows?.length)return '';return `<details class="symbol-box" ${open?'open':''}><summary>Що означають позначення?</summary><dl>${rows.map(([sym,desc,unit])=>`<div><dt>${guideEscape(sym)}</dt><dd>${guideEscape(desc)} <span class="symbol-unit">${unit&&unit!=='—'?' · '+guideEscape(unit):''}</span></dd></div>`).join('')}</dl></details>`;}
function renderWorkedText(t,i,inline=false){const e=guideEscape,g=t.guide||{};return `<article class="${inline?'inline-worked':'card'} worked-task" id="${inline?'note-task':'task'}-${i+1}"><div class="row spread"><span class="tag">${e(t.level)}</span>${t.record?'<span class="tag source-tag">З матеріалів заняття</span>':''}</div><h${inline?3:2}>${e(t.title||'Задача '+(i+1))}</h${inline?3:2}>${t.record?`<p class="task-record">${e(t.record)}</p>`:''}${t.source?`<small class="muted">${e(t.source)} · адаптована умова</small>`:''}<h3>Умова</h3><p>${e(t.q)}</p><div class="given-box"><div><strong>Дано</strong><p>${e(t.given)}</p></div><div><strong>Знайти</strong><p>${e(t.find)}</p></div></div><details class="symbol-box" open><summary>Позначення та одиниці вимірювання</summary><dl>${(g.vars||[]).map(row=>{const [sym,...rest]=row.split(' — ');return `<div><dt>${e(sym)}</dt><dd>${e(rest.join(' — '))}</dd></div>`}).join('')}</dl></details>${t.image?`<figure class="task-figure"><img loading="eager" src="${e(t.image)}" alt="Схема до задачі: ${e(t.title||'фізичне явище')}"><figcaption>${e(t.imageCaption||'Схема або графік до задачі.')}</figcaption></figure>`:''}<details><summary>Підказка</summary><p>${e(t.hint)}</p></details><details class="worked-solution" ${inline?'open':''}><summary>Детальне розв’язання з теорією</summary><div class="task-theory"><h3>Теорія та закони</h3><p>${e(g.theory)}</p></div><h3>Послідовність розв’язання</h3><ol class="solution-steps">${t.steps.map((step,j)=>`<li><strong>Крок ${j+1}</strong><p>${e(step)}</p></li>`).join('')}</ol><section class="notebook-solution"><h3>Основні рівняння · математичний запис</h3>${(g.math||[]).map(guideMath).join('')}</section><div class="solution-answer"><strong>Відповідь:</strong> ${e(t.answer)}</div><div class="task-check"><strong>Перевірка та фізичний зміст</strong><p>${e(g.check)}</p></div></details></article>`;}
function renderAllTasks(l){return `<div class="card source-note"><h2>Задачі та розв’язання</h2><p>${guideEscape(l.standard)}</p><p class="muted">Задачі із записів мають позначку джерела; адаптовані умови зі збірника мають номер і сторінку. Додаткові приклади — навчальні, не дослівний запис.</p><div class="row no-print"><button type="button" id="expand-tasks">Розкрити всі розв’язання</button><button type="button" id="print-tasks">Друк / зберегти PDF</button></div></div><div class="stack task-stack">${l.tasks.map((t,i)=>renderWorked(t,i)).join('')}</div>`;}
function setupTasks(b){const expand=b.querySelector('#expand-tasks');if(expand)expand.onclick=()=>{const ds=[...b.querySelectorAll('.worked-solution')];const open=ds.some(d=>!d.open);ds.forEach(d=>d.open=open);expand.textContent=open?'Згорнути всі розв’язання':'Розкрити всі розв’язання'};const print=b.querySelector('#print-tasks');if(print)print.onclick=()=>{b.querySelectorAll('.worked-solution,.symbol-box').forEach(d=>d.open=true);window.print()};}

function renderWorked(t,i,inline=false){
 if(!t.visual?.length)return renderWorkedText(t,i,inline);
 const e=guideEscape, title=t.title||'Задача '+(i+1), pic=(src,label)=>`<a class="visual-sheet-link" href="${e(src)}" target="_blank" rel="noopener"><img class="visual-sheet" src="${e(src)}" loading="lazy" alt="${e(label)}"></a>`;
 return `<article class="${inline?'inline-worked':'card'} worked-task visual-task" id="${inline?'note-task':'task'}-${i+1}"><div class="row spread"><span class="tag">${e(t.level)}</span>${t.record?'<span class="tag source-tag">З матеріалів заняття</span>':''}</div><h${inline?3:2}>${e(title)}</h${inline?3:2}>${pic(t.visual[0],t.q)}<details><summary>Підказка</summary><p>${e(t.hint)}</p></details><details class="worked-solution" ${inline?'open':''}><summary>Показати розв’язання в картинках</summary><div class="visual-sheets">${t.visual.slice(1).map((p,j)=>pic(p, title+' — частина '+(j+2))).join('')}</div></details><details class="visual-text no-print"><summary>Текстова версія (для пошуку та читання)</summary>${renderWorkedText(t,i,false).replace(/ id="task-\d+"/,'').replace('class="worked-solution"','class="accessible-solution" open')}</details></article>`;
}

;

// Structured, reusable lecture renderer. All authored text is escaped.
function renderReading(l, assets=window.MATH_ASSETS||{}){
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const rich=s=>esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 const img=(m,cls='')=>{const src=assets[m]||window.GUIDE_ASSETS?.[m];return src?`<img class="typeset ${cls}" src="${esc(src)}" alt="${esc(m)}">`:`<span class="eq">${esc(m)}</span>`;};
 const seen=new Set();const legend=m=>{const rows=l.symbols?.[m]||[];const fresh=rows.some(r=>!seen.has(r[0]+r[1]));rows.forEach(r=>seen.add(r[0]+r[1]));return guideSymbols(rows,fresh)};
 const block=b=>{const [k,x,y,z]=b;switch(k){case 'p':return `<p>${rich(x)}</p>`;case 'h':return `<h3>${esc(x)}</h3>`;case 'math':return `<figure class="math-block"><div class="math-line ${z?'boxed':''}">${img(x)}</div><figcaption>${esc(y)}</figcaption></figure>${legend(x)}`;case 'worked':return l.tasks?.[x]?renderWorked(l.tasks[x],x,true):'';case 'note':case 'example':return `<aside class="learning-note ${k}"><strong>${esc(x)}</strong><p>${rich(y)}</p></aside>`;case 'lecturer':return `<div class="lecturer-note"><div class="lecturer-label">${esc(x)}</div>${String(y).split('\n\n').map(t=>`<p>${rich(t)}</p>`).join('')}<small>Переказ змісту лекції, не дослівна цитата.</small></div>`;case 'figure':return `<figure class="lecture-figure"><img src="${esc(window.FIGURE_ASSETS?.[x]||'assets/'+x+'.svg')}" alt="${esc(y)}"><figcaption>${esc(y)}</figcaption></figure>`;default:return ''}};
 const table=l.formulaTable?.length?`<section class="reading-section formula-reference"><h2>Усі основні формули лекції</h2><table><thead><tr><th>Фізична величина</th><th>Формула</th></tr></thead><tbody>${l.formulaTable.map(([n,m])=>`<tr><td>${esc(n)}</td><td>${img(m)}${guideSymbols(l.symbols?.[m]||[],false)}</td></tr>`).join('')}</tbody></table></section>`:'';
 return `<article class="reading"><p class="reading-intro">Повний конспект · пояснення від базових понять до формул. Основна теорія викладена безпосередньо; усні акценти лектора та додаткові пояснення виділено окремими рамками. Нові позначення пояснюються під формулами; повторні довідки можна розкрити за потреби.</p><section class="reading-plan"><h2>План лекції</h2><table><thead><tr><th>Час (приблизно)</th><th>Тема</th></tr></thead><tbody>${l.reading.map(s=>`<tr><td>${esc(s.time)}</td><td>${esc(s.title.replace(/^\d+\. /,''))}</td></tr>`).join('')}</tbody></table></section>${l.reading.map(s=>`<section class="reading-section"><small class="reading-time">${esc(s.time)} · приблизно</small><h2>${esc(s.title)}</h2>${s.blocks.map(block).join('')}</section>`).join('')}${table}<section class="reading-section no-print"><h2>Перевір себе</h2><p>Пройди тест, розв’яжи задачі та зміни параметри у симуляціях, щоб закріпити матеріал.</p><div class="row"><a class="primary" href="#lecture/${esc(l.id)}/quiz">Пройти тест</a><a href="#lecture/${esc(l.id)}/tasks">Задачі</a><a href="#lecture/${esc(l.id)}/sim">Симуляції</a></div></section></article>`;
}
if(typeof module!=='undefined')module.exports=renderReading;

;
'use strict';
const L=window.LECTURES, app=document.querySelector('#app'), key='ya-programist-physics-v1';
const read=()=>{try{return JSON.parse(localStorage.getItem(key))||{}}catch{return {}}};let db=read();db.done??={};db.attempts??=[];db.cards??={};db.wrong??={};
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{toast('Не вдалося зберегти прогрес у цьому браузері.')}}
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const eq=s=>`<div class="eq">${E(s)}</div>`;const paras=a=>a.map(x=>`<p>${E(x)}</p>`).join('');const ordered=a=>`<ol>${a.map(x=>`<li>${E(x)}</li>`).join('')}</ol>`;
const find=id=>L.find(l=>l.id===id);const link=(l,t='notes')=>`#lecture/${encodeURIComponent(l.id)}/${t}`;
let toastTimer;function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',2600)}
const root=document.documentElement;try{root.dataset.theme=localStorage.getItem('physics-theme')|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{root.dataset.theme='light'};document.querySelector('#theme').onclick=()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('physics-theme',root.dataset.theme)}catch{}};
const attempts=()=>db.attempts;const average=()=>attempts().length?Math.round(attempts().reduce((a,b)=>a+b.score/b.total,0)/attempts().length*100):0;const done=()=>L.filter(l=>db.done[l.id]).length;const bad=()=>Object.entries(db.wrong).filter(([,v])=>v>0);const stats=()=>`<div class="stats"><div class="stat"><small>Лекцій у бібліотеці</small><div class="num">${L.length}</div></div><div class="stat"><small>Опрацьовано</small><div class="num">${done()} / ${L.length}</div></div><div class="stat"><small>Середній бал тестів</small><div class="num">${attempts().length?average()+'%':'—'}</div></div></div>`;
function lectureCard(l){return `<article class="card lecture-card"><div class="row spread"><span class="tag">${E(l.unit)}</span><small>${E(l.date)} ${db.done[l.id]?' · ✓ Опрацьовано':''}</small></div><h2>${E(l.title)}</h2><p class="muted">${E(l.description)}</p><small>${l.quiz.length} тестових запитань · ${l.tasks.length} задачі · ${E(l.duration)}</small><div class="row"><a class="primary" href="${link(l)}">Відкрити лекцію →</a><a href="${link(l,'quiz')}">До тесту</a></div></article>`}
const heroArt=`<svg class="hero-art" viewBox="0 0 240 220" aria-hidden="true"><g fill="none" stroke="#a7c1ff" stroke-width="1.4"><ellipse cx="120" cy="108" rx="95" ry="35" transform="rotate(-30 120 108)"/><ellipse cx="120" cy="108" rx="95" ry="35" transform="rotate(30 120 108)"/><ellipse cx="120" cy="108" rx="95" ry="35" transform="rotate(90 120 108)"/><circle cx="120" cy="108" r="10" fill="#a7c1ff"/><circle cx="43" cy="148" r="5" fill="#fff"/><circle cx="172" cy="170" r="5" fill="#fff"/><circle cx="125" cy="15" r="5" fill="#fff"/></g><g fill="#cbd8ff" font-family="serif" font-size="15"><text x="8" y="28">v = dr/dt</text><text x="152" y="207">F = ma</text></g></svg>`;
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">Твоя бібліотека з фізики</div><h1>Фізика, яку можна зрозуміти.</h1><p>Конспекти, формули, практичні задачі та самоперевірка — в одному місці.</p><a class="primary" href="#library">Перейти до лекцій →</a> <a class="primary" href="study/catalog.html">Відкрити курс КПІ</a></div>${heroArt}</section>${stats()}<div class="section-head"><h2>Навчальні матеріали</h2><a href="#library">Усі лекції →</a></div><div class="grid">${L.map(lectureCard).join('')}</div><div class="section-head"><h2>Підготовка до іспиту</h2></div><div class="grid"><article class="card"><span class="tag">Практика</span><h3>Пробний іспит</h3><p class="muted">Випадкові запитання з усіх доступних лекцій. Результат після завершення.</p><a href="#exam">Почати →</a></article><article class="card"><span class="tag">Повторення</span><h3>Робота над помилками</h3><p class="muted">Повтори теми, у яких помилився, та перевір себе ще раз.</p><a href="#mistakes">Мої помилки →</a></article></div>`}
function library(){app.innerHTML=`<div class="eyebrow">Бібліотека</div><h1>Лекції з фізики</h1><p class="muted">Шукай теми, терміни та формули у всіх конспектах.</p><input type="search" class="search" id="search" placeholder="Наприклад, прискорення або інтеграл" aria-label="Пошук лекцій"><div id="results" class="grid"></div>`;const inp=document.querySelector('#search'),res=document.querySelector('#results');function filter(){const q=inp.value.trim().toLocaleLowerCase('uk');const matches=L.filter(l=>JSON.stringify(l).toLocaleLowerCase('uk').includes(q));res.innerHTML=matches.length?matches.map(lectureCard).join(''):'<div class="empty">Нічого не знайдено. Спробуй інший запит.</div>'}inp.oninput=filter;filter()}
const tabs=[['notes','Конспект'],['short','Стисло'],['formulas','Формули'],['quiz','Тести'],['tasks','Задачі'],['cards','Картки'],['sim','Симуляції'],['oral','Усний залік'],['audio','Аудіоогляд']];
function lesson(l,tab){if(!l){app.innerHTML='<h1>Лекцію не знайдено</h1><a href="#library">До бібліотеки</a>';return} if(!tabs.some(t=>t[0]===tab))tab='notes';app.innerHTML=`<a class="no-print" href="#library">← Усі лекції</a><div class="row spread" style="margin-top:13px"><span class="tag">${E(l.unit)} · ${E(l.date)}</span><small>${E(l.duration)}</small></div><h1 style="margin-top:12px">${E(l.title)}</h1><p class="muted">${E(l.description)}</p><div class="row no-print"><button id="done">${db.done[l.id]?'✓ Опрацьовано':'Позначити опрацьованою'}</button><a class="primary" href="${E(l.pdf)}" download>↓ PDF</a><button id="share">Поділитися</button></div><div class="tabs" role="navigation" aria-label="Розділи лекції">${tabs.map(([id,n])=>`<button class="${id===tab?'selected':''}" data-tab="${id}">${n}</button>`).join('')}</div><div id="lesson-body"></div><p class="muted" style="margin-top:24px;font-size:12px">${E(l.source)}</p>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>location.hash=link(l,b.dataset.tab));document.querySelector('#done').onclick=()=>{db.done[l.id]=!db.done[l.id];save();document.querySelector('#done').textContent=db.done[l.id]?'✓ Опрацьовано':'Позначити опрацьованою'};document.querySelector('#share').onclick=async()=>{const url=new URL(link(l,tab),location.href).href;try{if(navigator.share){await navigator.share({title:l.title,url})}else if(navigator.clipboard){await navigator.clipboard.writeText(url);toast('Посилання скопійовано')}else{prompt('Скопіюй посилання:',url)}}catch(e){if(e.name!=='AbortError')prompt('Скопіюй посилання:',url)}};const b=document.querySelector('#lesson-body');
if(tab==='notes'){
 const fallback=()=>`<div class="stack">${(l.sections||[]).map(s=>`<article class="card note"><small>${E(s.time)} · приблизний таймкод</small><h2>${E(s.title)}</h2>${paras(s.text||[])}${(s.equations||[]).map(eq).join('')}</article>`).join('')}</div>`;
 try {const html=l.reading?renderReading(l):fallback();if(!html.trim())throw new Error('Empty notes');b.innerHTML=html;}
 catch(err){console.error('Notes rendering failed',err);b.innerHTML='<article class="card"><h2>Спрощений режим конспекту</h2><p>Не вдалося відобразити розширене оформлення. Основний текст доступний нижче. Спробуй оновити сторінку; також доступний PDF.</p></article>'+fallback();}
}
if(tab==='short')b.innerHTML=`<article class="card"><h2>Головне за 5 хвилин</h2>${ordered(l.summary)}</article>`;
if(tab==='formulas')b.innerHTML=`<div class="stack">${l.formulas.map(f=>`<article class="card"><h2>${E(f.name)}</h2>${guideMath(f.latex)||eq(f.eq)}${f.extraLatex?guideMath(f.extraLatex):''}<p class="muted">${E(f.vars)}</p>${guideSymbols(l.symbols?.[f.latex]||[],true)}<details><summary>Покрокове виведення</summary>${ordered(f.steps)}</details></article>`).join('')}</div>`;
if(tab==='quiz')quizStart(b,l.quiz.map((q,i)=>({...q,k:l.id+':'+i,lesson:l.id})),l.title,false);
if(tab==='tasks'){b.innerHTML=renderAllTasks(l);setupTasks(b);}
if(tab==='audio')podcast(b,l);
if(tab==='cards')flash(b,l);
if(tab==='sim'){if(l.simulation==='kinematics')simulate(b);else if(['curvature','rolling'].includes(l.simulation))topicSim(b,l.simulation);else if(['turning','friction'].includes(l.simulation))newTopicSim(b,l.simulation);else b.innerHTML='<div class="card">Симуляції для цієї теми ще не додані.</div>'}
if(tab==='oral')b.innerHTML=`<div class="card"><h2>Усний залік</h2><p class="muted">Спочатку поясни відповідь уголос, а потім звір її з орієнтиром. Самооцінювання, без автоматичної перевірки мовлення.</p>${l.oral.map(([q,a])=>`<details><summary>${E(q)}</summary><p>${E(a)}</p></details>`).join('')}</div>`}
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
function quizStart(el,items,title,exam){if(!items.length){el.innerHTML='<div class="card empty">Немає запитань.</div>';return}el.innerHTML=`<article class="card"><span class="tag">${exam?'Іспит':'Самоперевірка'}</span><h2>${E(title)}</h2><p>${items.length} запитань. ${exam?'Пояснення після завершення.':'Пояснення після кожної відповіді.'}</p><label class="quiz-size">Кількість запитань <select id="quizcount">${[10,20,30,items.length].filter((n,i,a)=>n<=items.length&&a.indexOf(n)===i).map(n=>`<option value="${n}" ${n===items.length?'selected':''}>${n===items.length?`Усі (${n})`:n}</option>`).join('')}</select></label><button class="primary" id="startquiz">Розпочати</button></article>`;el.querySelector('#startquiz').onclick=()=>runQuiz(el,shuffle(items).slice(0,Number(el.querySelector('#quizcount').value)),title,exam)}
function detailedFeedback(q,picked){return `<div class="answer-review"><p><strong>Правильна відповідь:</strong> ${E(q.o[q.a])}</p>${picked!==q.a?`<p><strong>Твій вибір:</strong> ${E(q.o[picked])}</p>`:''}<h3>Чому саме так?</h3><p>${E(q.why)}</p>${q.detail?.length>1?`<details open><summary>Покрокове обґрунтування</summary>${ordered(q.detail)}</details>`:''}${q.image?`<figure class="task-figure"><img src="${E(q.image)}" alt="Схема до пояснення"><figcaption>Графічне пояснення</figcaption></figure>`:''}${q.source?`<small class="muted">${E(q.source)}</small>`:''}${q.reviewSection?`<p class="muted">Повтори розділ: ${E(q.reviewSection)}</p>`:''}${q.lesson?`<p><a href="${link(find(q.lesson))}">До теорії цієї лекції →</a></p>`:''}</div>`}
function runQuiz(el,qs,title,exam){let i=0,answers=[],picked=null,locked=false;function draw(){let q=qs[i];el.innerHTML=`<article class="card"><div class="row spread"><small>Запитання ${i+1} з ${qs.length}</small><span class="tag">${E(q.topic)}</span></div><div class="bar"><span style="width:${100*i/qs.length}%"></span></div><h2 style="margin-top:20px">${E(q.q)}</h2>${q.context?`<div class="quiz-context"><strong>Умова задачі:</strong> ${E(q.context)}</div>`:''}<div class="options">${q.o.map((o,n)=>`<button data-opt="${n}" class="${locked&&!exam?(n===q.a?'correct':n===picked?'wrong':''):picked===n?'chosen':''}" ${locked?'disabled':''}>${String.fromCharCode(65+n)}. ${E(o)}</button>`).join('')}</div>${locked&&!exam?`<div class="feedback"><strong>${picked===q.a?'Правильно!':'Помилка'}</strong>${detailedFeedback(q,picked)}</div>`:''}<button class="primary" id="nextq" ${picked===null?'disabled':''}>${locked?(i===qs.length-1?'Результат':'Далі'):'Підтвердити відповідь'}</button></article>`;el.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{picked=+b.dataset.opt;draw()});el.querySelector('#nextq').onclick=()=>{if(!locked){answers.push(picked);locked=true;draw()}else if(i+1<qs.length){i++;picked=null;locked=false;draw()}else finish()}}
function finish(){const score=answers.filter((a,n)=>a===qs[n].a).length;qs.forEach((q,n)=>{db.wrong[q.k]=answers[n]===q.a?0:(db.wrong[q.k]||0)+1});db.attempts.push({title,score,total:qs.length,date:new Date().toISOString()});save();el.innerHTML=`<article class="card"><div class="eyebrow">Результат</div><div class="num">${Math.round(score/qs.length*100)}%</div><h2>${score} з ${qs.length} правильних</h2><div class="bar"><span style="width:${score/qs.length*100}%"></span></div><div class="row" style="margin-top:18px"><button id="retry" class="primary">Пройти ще раз</button><a href="#mistakes">Мої помилки →</a></div></article><div class="section-head"><h2>Розбір відповідей</h2></div><div class="stack">${qs.map((q,n)=>`<article class="card"><span class="tag">${answers[n]===q.a?'✓ Правильно':'Потрібно повторити'}</span><h3>${E(q.q)}</h3><p>Твоя відповідь: ${E(q.o[answers[n]])}</p><p><strong>Правильна:</strong> ${E(q.o[q.a])}</p>${detailedFeedback(q,answers[n])}</article>`).join('')}</div>`;el.querySelector('#retry').onclick=()=>runQuiz(el,shuffle(qs),title,exam)}draw()}
function allQ(){return L.flatMap(l=>l.quiz.map((q,i)=>({...q,k:l.id+':'+i,lesson:l.id})))}
function exam(){app.innerHTML='<div class="eyebrow">Самопідготовка</div><h1>Пробний іспит</h1><p class="muted">Завдання з усіх доступних лекцій. Це тренування, а не офіційна оцінка.</p><div id="exam-body"></div>';quizStart(document.querySelector('#exam-body'),shuffle(allQ()).slice(0,20),'Фізика · пробний іспит',true)}
function flash(el,l){let i=0,flip=false;db.cards[l.id]??={};function draw(){let c=l.cards[i],known=db.cards[l.id][i];el.innerHTML=`<article class="card"><div class="row spread"><small>Картка ${i+1} з ${l.cards.length}</small><small>${Object.values(db.cards[l.id]).filter(Boolean).length} вивчено</small></div><button class="flash" id="flip"><small>${flip?'ВІДПОВІДЬ':'ЗАПИТАННЯ · НАТИСНИ, ЩОБ ПЕРЕВЕРНУТИ'}</small>${E(c[flip?1:0])}</button><div class="row spread" style="margin-top:12px"><button id="prev">←</button><button id="learned" ${flip?'':'disabled'}>${known?'✓ Вивчено':'Позначити вивченою'}</button><button id="again" ${flip?'':'disabled'}>Повторити</button><button id="next">→</button></div></article>`;el.querySelector('#flip').onclick=()=>{flip=!flip;draw()};el.querySelector('#prev').onclick=()=>{i=(i+l.cards.length-1)%l.cards.length;flip=false;draw()};el.querySelector('#next').onclick=()=>{i=(i+1)%l.cards.length;flip=false;draw()};el.querySelector('#learned').onclick=()=>{db.cards[l.id][i]=true;save();i=(i+1)%l.cards.length;flip=false;draw()};el.querySelector('#again').onclick=()=>{db.cards[l.id][i]=false;save();i=(i+1)%l.cards.length;flip=false;draw()}}draw()}
function simulate(el){el.innerHTML=`<div class="stack"><article class="card"><h2>Рух зі сталим прискоренням</h2><p class="muted">Змінюй початкову швидкість, прискорення і час. Початкова координата x₀=0.</p><div id="ranges">${[['v0','Початкова швидкість, м/с',-5,10,1,2],['a','Прискорення, м/с²',-4,4,.5,2],['t','Час, с',0,10,.25,4]].map(([id,n,min,max,step,v])=>`<label class="range" for="${id}"><span>${n}</span><strong id="${id}-val"></strong><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${v}"></label>`).join('')}</div><div class="row spread"><button id="play">▶ Відтворити рух</button><div class="metric" id="live"></div></div><div id="graphs" class="grid" style="margin-top:15px"></div></article><article class="card"><h2>Проєкції вектора</h2><label class="range" for="alpha"><span>Кут до осі X, °</span><strong id="alpha-val"></strong><input id="alpha" type="range" min="0" max="360" value="40"></label><label class="range" for="mag"><span>Модуль вектора</span><strong id="mag-val"></strong><input id="mag" type="range" min="1" max="8" step=".5" value="5"></label><div id="projection"></div></article></div>`;const get=id=>+el.querySelector('#'+id).value;const label=(id,v)=>el.querySelector('#'+id+'-val').textContent=v;const fmt=x=>Number(x.toFixed(2)).toLocaleString('uk');
function graph(fn,name,unit,t){const W=340,H=210,p=37,r=12,b=35,top=17;const vals=Array.from({length:101},(_,i)=>fn(i/10));let lo=Math.min(0,...vals),hi=Math.max(0,...vals);if(hi===lo){hi=1;lo=-1}const pad=(hi-lo)*.06;hi+=pad;lo-=pad;const X=x=>p+x/10*(W-p-r),Y=y=>top+(hi-y)/(hi-lo)*(H-top-b);const line=vals.map((v,i)=>`${i?'L':'M'}${X(i/10).toFixed(1)},${Y(v).toFixed(1)}`).join(' ');return `<div><h3>${name}</h3><svg class="graph" viewBox="0 0 ${W} ${H}" aria-label="${name}"><g stroke="currentColor" opacity=".24">${[0,2,4,6,8,10].map(x=>`<path d="M${X(x)} ${top}V${H-b}"/>`).join('')}${Array.from({length:5},(_,i)=>`<path d="M${p} ${Y(lo+(hi-lo)*i/4)}H${W-r}"/>`).join('')}</g><g font-size="10" fill="currentColor">${[0,2,4,6,8,10].map(x=>`<text x="${X(x)}" y="${H-17}" text-anchor="middle">${x}</text>`).join('')}<text x="${p-4}" y="${Y(hi)+4}" text-anchor="end">${fmt(hi)}</text><text x="${p-4}" y="${Y(lo)}" text-anchor="end">${fmt(lo)}</text><text x="${p-4}" y="${Y(0)+4}" text-anchor="end">0</text><text x="${W-10}" y="${H-4}" text-anchor="end">t, с</text><text x="6" y="12">${unit}</text></g><path d="M${p} ${Y(0)}H${W-r}" stroke="currentColor" opacity=".7"/><path d="${line}" fill="none" stroke="#4778f5" stroke-width="2.7"/><path d="M${X(t)} ${top}V${H-b}" stroke="#e59836" stroke-dasharray="4 4"/><circle cx="${X(t)}" cy="${Y(fn(t))}" r="4.5" fill="#e59836"/></svg></div>`}
function update(){const v=get('v0'),a=get('a'),t=get('t');['v0','a','t'].forEach(id=>label(id,fmt(get(id))));const x=u=>v*u+a*u*u/2,vel=u=>v+a*u;el.querySelector('#live').textContent=`x = ${fmt(x(t))} м · v = ${fmt(vel(t))} м/с`;el.querySelector('#graphs').innerHTML=graph(x,'Координата x(t)','м',t)+graph(vel,'Швидкість v(t)','м/с',t)+graph(()=>a,'Прискорення a(t)','м/с²',t);}
function project(){const a=get('alpha'),m=get('mag'),x=m*Math.cos(a*Math.PI/180),y=m*Math.sin(a*Math.PI/180),X=170+x*15,Y=145-y*15;label('alpha',a+'°');label('mag',fmt(m));el.querySelector('#projection').innerHTML=`<svg class="graph" viewBox="0 0 340 290" aria-label="Проєкції вектора"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#4778f5"/></marker></defs><path d="M15 145H325M170 10V280" stroke="currentColor"/><g fill="currentColor" font-size="12"><text x="324" y="138">X</text><text x="178" y="14">Y</text><text x="175" y="160">0</text></g><path d="M${X} 145V${Y}H170" fill="none" stroke="#e59836" stroke-dasharray="4 4"/><path d="M170 145L${X} 145" stroke="#e59836" stroke-width="3"/><path d="M170 145L170 ${Y}" stroke="#2caa80" stroke-width="3"/><path d="M170 145L${X} ${Y}" stroke="#4778f5" stroke-width="3" marker-end="url(#arrow)"/></svg><div class="row spread" style="margin-top:10px"><strong>aₓ = ${fmt(x)}</strong><strong>aᵧ = ${fmt(y)}</strong></div>`}
['v0','a','t'].forEach(id=>el.querySelector('#'+id).oninput=update);['alpha','mag'].forEach(id=>el.querySelector('#'+id).oninput=project);let timer;el.querySelector('#play').onclick=()=>{let b=el.querySelector('#play');if(timer){clearInterval(timer);timer=null;b.textContent='▶ Відтворити рух';return}const t=el.querySelector('#t');t.value=0;b.textContent='Ⅱ Пауза';update();timer=setInterval(()=>{if(!el.isConnected||+t.value>=10){clearInterval(timer);timer=null;b.textContent='▶ Відтворити рух';return}t.value=+t.value+.25;update()},125)};update();project()}
function glossary(){app.innerHTML='<div class="eyebrow">Довідник</div><h1>Словник термінів</h1><input id="term" class="search" type="search" placeholder="Знайти термін" aria-label="Пошук термінів"><div id="terms" class="stack"></div>';const arr=L.flatMap(l=>l.glossary.map(([n,d])=>({n,d,l}))).sort((a,b)=>a.n.localeCompare(b.n,'uk'));const t=document.querySelector('#term');function draw(){const q=t.value.toLocaleLowerCase('uk');const a=arr.filter(x=>(x.n+' '+x.d).toLocaleLowerCase('uk').includes(q));document.querySelector('#terms').innerHTML=a.map(x=>`<article class="card"><h3>${E(x.n)}</h3><p>${E(x.d)}</p><a href="${link(x.l)}">${E(x.l.title)} →</a></article>`).join('')||'<div class="empty">Термін не знайдено.</div>'}t.oninput=draw;draw()}
function progress(){app.innerHTML=`<div class="eyebrow">Особистий кабінет</div><h1>Мій прогрес</h1><p class="muted">Дані зберігаються лише на цьому пристрої та у цьому браузері. Синхронізації між пристроями немає.</p>${stats()}<div class="stack">${L.map(l=>{const a=attempts().filter(a=>a.title===l.title || (l.id==='kinematics-01' && a.title==='Кінематика матеріальної точки')),best=a.length?Math.round(Math.max(...a.map(x=>x.score/x.total))*100):0;return `<article class="card"><h3><a href="${link(l)}">${E(l.title)}</a></h3><p>Найкращий тест: ${a.length?best+'%':'ще не пройдено'} · Картки: ${Object.values(db.cards[l.id]||{}).filter(Boolean).length}/${l.cards.length}</p><div class="bar"><span style="width:${best}%"></span></div></article>`}).join('')}</div><div class="section-head"><h2>Історія спроб</h2></div><div class="stack">${[...attempts()].reverse().slice(0,50).map(a=>`<article class="card row spread"><span>${E(a.title)}<br><small>${new Date(a.date).toLocaleString('uk')}</small></span><strong>${a.score}/${a.total}</strong></article>`).join('')||'<div class="card empty">Ще немає спроб.</div>'}</div><button id="reset" style="margin-top:20px">Скинути локальний прогрес</button>`;document.querySelector('#reset').onclick=()=>{if(confirm('Видалити всі результати з цього браузера?')){db={done:{},attempts:[],cards:{},wrong:{}};save();progress()}}}
function mistakes(){const qs=allQ().filter(q=>db.wrong[q.k]>0);app.innerHTML=`<div class="eyebrow">Повторення</div><h1>Мої помилки</h1><p class="muted">Запитання, на які останнього разу відповів неправильно. Після правильної відповіді вони зникають зі списку.</p><div id="wrongquiz"></div><div class="stack" style="margin-top:16px">${qs.map(q=>`<article class="card"><span class="tag">${E(q.topic)}</span><h3>${E(q.q)}</h3><details><summary>Пояснення</summary><p>${E(q.why)}</p><a href="${link(find(q.lesson))}">Повторити лекцію</a></details></article>`).join('')}</div>`;if(qs.length)quizStart(document.querySelector('#wrongquiz'),qs,'Робота над помилками',false);else document.querySelector('#wrongquiz').innerHTML='<div class="card empty">Немає запитань для повторення. Пройди тест, щоб почати.</div>'}
function route(){document.querySelectorAll('audio').forEach(a=>{a.pause();a.removeAttribute('src');a.load();});if('speechSynthesis' in window)window.speechSynthesis.cancel();const [page,id,tab]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===(page==='lecture'?'library':page||'home')));switch(page){case 'library':library();break;case 'lecture':lesson(find(decodeURIComponent(id||'')),tab||'notes');break;case 'exam':exam();break;case 'audio':audioLibrary();break;case 'glossary':glossary();break;case 'progress':progress();break;case 'mistakes':mistakes();break;default:home()}window.scrollTo(0,0)}window.addEventListener('hashchange',route);route();

function topicSim(el,kind){
 const roll=kind==='rolling';
 el.innerHTML=`<article class="card"><h2>${roll?'Кочення диска без проковзування':'Тангенціальне й нормальне прискорення'}</h2><p class="muted">${roll?'Обери точку диска та швидкість центра. Стрілки показують швидкість відносно дороги.':'Змінюй швидкість, радіус кривини й тангенціальне прискорення. Стрілки показують напрям і відносну величину складових.'}</p><div class="stack">${(roll?[['speed','Швидкість центра, м/с',0.5,8,.5,3],['radius','Радіус, м',.2,2,.1,.6],['angle','Кут точки від правого краю, °',0,360,5,90]]:[['speed','Модуль швидкості, м/с',1,10,.5,5],['radius','Радіус кривини, м',1,20,.5,5],['tangent','Тангенціальне прискорення, м/с²',-10,10,.5,2]]).map(([id,n,min,max,step,v])=>`<label class="range"><span>${n}</span><strong id="${id}-val"></strong><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${v}"></label>`).join('')}</div><div id="topic-figure"></div><div id="topic-metrics" class="metric"></div></article>`;
 const get=id=>Number(el.querySelector('#'+id).value),fmt=x=>Number(x.toFixed(2)).toLocaleString('uk');
 function draw(){const v=get('speed'),r=get('radius'); el.querySelectorAll('input').forEach(x=>el.querySelector('#'+x.id+'-val').textContent=fmt(+x.value));const cx=170,cy=138,R=82;let body='',metrics='';const arrow=(x,y,dx,dy,c,m)=>Math.hypot(dx,dy)<.001?'':`<path d="M${x} ${y}l${dx} ${dy}" stroke="${c}" stroke-width="3.5" marker-end="url(#${m})"/>`;
 if(roll){const th=get('angle')*Math.PI/180,x=cx+R*Math.cos(th),y=cy-R*Math.sin(th),vx=v*(1+Math.sin(th)),vy=v*Math.cos(th),mag=Math.hypot(vx,vy),scale=60/v;body=`<path d="M20 ${cy+R}H360" stroke="currentColor" stroke-width="3"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="currentColor" stroke-width="2"/><path d="M${cx} ${cy}L${x} ${y}M${cx} ${cy+R}L${x} ${y}" stroke="currentColor" opacity=".4" stroke-dasharray="4 4"/><circle cx="${x}" cy="${y}" r="5" fill="#2563eb"/><circle cx="${cx}" cy="${cy+R}" r="4" fill="#db3937"/>${arrow(x,y,v*scale,0,'#15803d','green')}${arrow(x,y,v*Math.sin(th)*scale,v*Math.cos(th)*scale,'#db3937','red')}${arrow(x,y,vx*scale,vy*scale,'#2563eb','blue')}<text x="${cx-12}" y="${cy-8}" fill="currentColor">O</text><text x="${cx-10}" y="${cy+R+21}" fill="currentColor">C</text><text x="${x-12}" y="${y-10}" fill="currentColor">P</text>`;metrics=`ω = ${fmt(v/r)} рад/с · v точки P = ${fmt(mag)} м/с · зелений: переносна, червоний: обертальна, синій: результуюча`;}
 else{const t=get('tangent'),n=v*v/r,scale=80/Math.max(Math.abs(t),n,1),x=cx+R,y=cy;body=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="currentColor" stroke-dasharray="5 4"/><circle cx="${x}" cy="${y}" r="5" fill="#2563eb"/><path d="M${cx} ${cy}H${x}" stroke="currentColor" opacity=".4"/>${arrow(x,y,-n*scale,0,'#db3937','red')}${arrow(x,y,0,-t*scale,'#15803d','green')}${arrow(x,y,-n*scale,-t*scale,'#2563eb','blue')}<text x="${x+10}" y="${y-48}" fill="currentColor">↑ v</text><text x="${cx-8}" y="${cy+18}" fill="currentColor">O</text>`;metrics=`aτ = ${fmt(t)} м/с² · aₙ = ${fmt(n)} м/с² · a = ${fmt(Math.hypot(t,n))} м/с² · червоний: нормальна, зелений: дотична, синій: повна`;}
 el.querySelector('#topic-figure').innerHTML=`<svg class="graph" viewBox="0 0 420 265" role="img" aria-label="Вектори кінематики"><defs>${[['blue','#2563eb'],['red','#db3937'],['green','#15803d']].map(([id,c])=>`<marker id="${id}" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0L7 3.5L0 7Z" fill="${c}"/></marker>`).join('')}</defs>${body}</svg>`;el.querySelector('#topic-metrics').textContent=metrics;}
 el.querySelectorAll('input').forEach(i=>i.oninput=draw);draw();}

function newTopicSim(b,kind){
const turn=kind==='turning';b.innerHTML=`<div class="card"><h2>${turn?'Рух із точкою повороту':'Тертя спокою та ковзання'}</h2><p>${turn?'Закон з практики: x(t)=6t−0,125t³. Змінюй час і спостерігай за знаком швидкості та накопиченим шляхом.':'Модель з лекції: брусок 1 кг, μ=0,1, g=10 м/с²; максимальне тертя 1 Н. Змінюй прикладену силу.'}</p><label>${turn?'Час (с)':'Прикладена сила (Н)'} <input id="newrange" type="range" min="0" max="${turn?6:2}" step="0.05" value="${turn?4:0.5}"></label><div id="newmetrics"></div><svg id="newplot" viewBox="0 0 580 235" role="img" aria-label="Інтерактивний графік" style="max-width:100%;width:100%;height:auto"></svg></div>`;const inp=b.querySelector('#newrange'),met=b.querySelector('#newmetrics'),plot=b.querySelector('#newplot');function draw(){const t=+inp.value,x=u=>6*u-.125*u*u*u,v=6-.375*t*t,force=Math.min(t,1);met.innerHTML=turn?`<p><b>t=${t.toFixed(2)} с · x=${x(t).toFixed(3)} м · vₓ=${v.toFixed(3)} м/с</b></p><p>Шлях S=${(t<=4?x(t):32-x(t)).toFixed(3)} м; aₓ=${(-.75*t).toFixed(2)} м/с². ${t<4?'Рух у додатному напрямі':t>4?'Рух у від’ємному напрямі':'Момент повороту'}</p>`:`<p><b>F=${t.toFixed(2)} Н · Fтер=${force.toFixed(2)} Н</b></p><p>${t<1?'Спокій: тертя урівноважує прикладену силу.':t===1?'Граничний стан спокою.':'Ковзання: у спрощенні лекції Fтер≈1 Н.'}</p>`;const X=u=>45+500*u/(turn?6:2),Y=u=>195-145*u/(turn?18:1.2);const val=u=>turn?x(u):Math.min(u,1);let pts=Array.from({length:121},(_,i)=>{const u=(turn?6:2)*i/120;return X(u)+','+Y(val(u))}).join(' ');plot.innerHTML=`<path d="M45 195H555M45 195V22" stroke="currentColor" opacity=".6" fill="none"/><text x="48" y="18" fill="currentColor" font-size="12">${turn?'x, м':'Fтер, Н'}</text><text x="510" y="225" fill="currentColor" font-size="12">${turn?'t, с':'F, Н'}</text><polyline points="${pts}" stroke="#2682df" stroke-width="3" fill="none"/><circle cx="${X(t)}" cy="${Y(val(t))}" r="6" fill="#e66b3f"/><path d="M${X(t)} 195V${Y(val(t))}" stroke="currentColor" stroke-dasharray="4 4" opacity=".5"/>`;};inp.oninput=draw;draw();}

function audioLibrary(){app.innerHTML=`<div class="eyebrow">Аудіоповторення</div><h1>Фізика на слух</h1><p class="muted">Один безперервний подкаст на кожне заняття: пояснення теорії, формул, прикладів та питання до іспиту. MP3 працюють після генерації й публікації файлів.</p><div class="grid">${L.map(l=>`<article class="card"><span class="tag">${E(l.date)}</span><h2>${E(l.title)}</h2><p>Один повний аудіоогляд · приблизно ${Math.ceil(l.podcast.map(p=>p.text).join(' ').split(/\s+/).length/120)} хв</p><a class="primary" href="${link(l,'audio')}">▶ Слухати</a></article>`).join('')}</div>`}
function podcast(el,l){
 const parts=l.podcast||[], script=parts.map(p=>p.title+'. '+p.text).join('\n\n');let token=0,utter=null;const synth=window.speechSynthesis;const path='audio/'+encodeURIComponent(l.id)+'-full-v144.mp3';
 el.innerHTML=`<article class="card podcast-card"><span class="tag">Повний подкаст · MP3</span><h2>${E(l.title)}</h2><p>Один аудіофайл на всю тему. Авторське пояснення українською, не запис голосу лектора.</p><div class="podcast-controls"><label>Швидкість <select id="podspeed"><option value="0.8">0,8×</option><option value="1" selected>1×</option><option value="1.2">1,2×</option><option value="1.5">1,5×</option><option value="2">2×</option></select></label></div><audio id="podplayer" controls preload="metadata" style="width:100%;margin:12px 0" aria-label="Повний аудіоогляд"></audio><div class="row"><button id="podback" disabled>−15 с</button><button id="podforward" disabled>+15 с</button><a id="poddownload" hidden download>↓ Завантажити MP3</a></div><p id="podstatus" role="status" class="muted"></p><details><summary>План аудіоогляду</summary>${ordered(parts.map(p=>p.title))}</details><details><summary>Резервне озвучення браузером</summary><p>Працює лише за наявності українського голосу на пристрої.</p><div class="row"><button id="podspeak">▶ Озвучити всю тему</button><button id="podpause">Пауза / продовжити</button><button id="podstop">■ Зупинити</button></div><p id="podtts" role="status"></p></details><p><a href="audio/${E(l.id)}.txt?v=144" download>↓ Завантажити сценарій (TXT)</a></p><details><summary>Повний текст аудіоогляду</summary>${parts.map(p=>`<h3>${E(p.title)}</h3><p>${E(p.text)}</p>`).join('')}</details></article>`;
 const $=id=>el.querySelector('#'+id),a=$('podplayer'),status=t=>$('podstatus').textContent=t;const speed=()=>Number($('podspeed').value);
 function stopSpeech(){token++;if(synth)synth.cancel();utter=null;}
 a.onloadedmetadata=()=>{status('Готово до прослуховування.');$('poddownload').hidden=false;$('podback').disabled=$('podforward').disabled=false;a.playbackRate=speed();};a.onplaying=()=>{stopSpeech();status('Відтворюється повний аудіоогляд.');};a.onerror=()=>{status('Повний MP3 ще не опубліковано або файл недоступний. Власнику сайту: запусти Generate_audio_windows.bat і опублікуй нові файли папки audio.');$('poddownload').hidden=true;};a.onended=()=>status('Аудіоогляд завершено.');$('poddownload').href=path;$('podspeed').onchange=()=>{a.playbackRate=speed();};$('podback').onclick=()=>{a.currentTime=Math.max(0,a.currentTime-15);};$('podforward').onclick=()=>{if(Number.isFinite(a.duration))a.currentTime=Math.min(a.duration,a.currentTime+15);};
 $('podspeak').onclick=()=>{a.pause();stopSpeech();if(!synth||!window.SpeechSynthesisUtterance){$('podtts').textContent='Браузер не підтримує озвучення.';return;}const voice=synth.getVoices().find(v=>/^uk(?:[-_]|$)/i.test(v.lang));if(!voice){$('podtts').textContent='Український голос не знайдено. Скористайся MP3 після публікації.';return;}const chunks=(script.match(/[^.!?]+[.!?]*\s*/g)||[script]).map(s=>s.trim()).filter(Boolean);const t=token;let i=0;function next(){if(t!==token||!el.isConnected)return;if(i===chunks.length){$('podtts').textContent='Озвучення завершено.';return;}utter=new SpeechSynthesisUtterance(chunks[i++]);utter.lang='uk-UA';utter.voice=voice;utter.rate=speed();utter.onend=next;utter.onerror=e=>{if(t===token)$('podtts').textContent='Помилка озвучення: '+e.error;};synth.speak(utter);}$('podtts').textContent='Озвучення всієї теми…';next();};$('podpause').onclick=()=>{if(synth?.paused)synth.resume();else if(synth?.speaking)synth.pause();};$('podstop').onclick=()=>{stopSpeech();$('podtts').textContent='Зупинено.';};
 if(parts.length){status('Завантаження повного MP3…');a.src=path;a.load();}else status('Сценарій відсутній.');
}

;
// Draw vector accents with CSS, rather than the unsupported combining glyph U+20D7.
function fixVectorNotation(rootNode){
 const walker=document.createTreeWalker(rootNode,NodeFilter.SHOW_TEXT), nodes=[];let n;
 while(n=walker.nextNode())if(n.data.includes('\u20d7')&&!n.parentElement.closest('.vector-glyph,script,style,textarea,option,svg'))nodes.push(n);
 for(const node of nodes){
  let text=node.data.replace(/d\u20d7([A-Za-zΑ-ω])/g,'d$1\u20d7').replace(/×\u20d7([A-Za-zΑ-ω])/g,'×$1\u20d7').replace(/([A-Za-zΑ-ω])([′₀-₉]+)\u20d7/g,'$1\u20d7$2');
  const re=/([A-Za-zΑ-ω0-9])\u20d7/g, fragment=document.createDocumentFragment();let m,last=0;
  while(m=re.exec(text)){fragment.append(document.createTextNode(text.slice(last,m.index).replace(/\u20d7/g,'')));const v=document.createElement('span');v.className='vector-glyph';v.textContent=m[1];v.setAttribute('aria-label','вектор '+m[1]);fragment.append(v);last=re.lastIndex;}
  fragment.append(document.createTextNode(text.slice(last).replace(/\u20d7/g,'')));node.replaceWith(fragment);
 }
}
const vectorObserver=new MutationObserver(()=>fixVectorNotation(app));vectorObserver.observe(app,{subtree:true,childList:true,characterData:true});fixVectorNotation(app);
